effect.shader:
float gAsp = 1.0;

float gray(vec3 c){ return dot(c, vec3(0.299, 0.587, 0.114)); }
float satv(float x){ return clamp(x, 0.0, 1.0); }
vec3  satv(vec3 c){ return clamp(c, 0.0, 1.0); }

// LAYER -> SCREEN. The blob field is generated in layer space and the luma it
// is driven by is read from the layer's own pixels, so the pattern is printed on
// the layer and travels with it instead of sitting on the screen.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }

// PREMULTIPLIED in: the luma that drives the bands must be straight colour. On
// premultiplied pixels every soft edge of the layer reads as black and gets
// pushed to the bottom of the ramp, which is what made this effect look broken.
vec3 colL(vec2 lp){
vec4 s = fetchL(lp);
return s.rgb / max(s.a, 1e-4);
}

float hash(vec2 p){
return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453123);
}
float smoothNoise(vec2 p){
vec2 i = floor(p);
vec2 f = fract(p);
f = f * f * (3.0 - 2.0 * f);
float bottom = mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x);
float top = mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x);
return mix(bottom, top, f.y);
}
float fbm(vec2 p){
float v = 0.0;
float a = 0.5;
vec2 shift = vec2(100.0);
for (int i = 0; i < 6; i++){
if (float(i) >= float(blobOctaves)) break;
v += a * smoothNoise(p);
p = p * 2.0 + shift;
a *= 0.5;
}
return v;
}

void main(){
vec2 lp = acLayerNorm;
gAsp = acLayerSize.x / max(acLayerSize.y, 1.0);
vec4 srcSample = fetchL(lp);
float sA = srcSample.a;
vec3 srcRGB = srcSample.rgb / max(sA, 1e-4);
float srcLuma = gray(srcRGB);

// The field is generated in aspect-corrected layer space so the blobs stay round
// whatever shape the layer is.
vec2 noiseUV = vec2(lp.x * gAsp, lp.y) * noiseFreq;

// Domain warp: displacing the coordinate by another fbm before evaluating it is
// what turns round blobs into the folded, lava-lamp shapes the effect is named
// for. Cheap, and it is the difference between this and plain noise contours.
if (warp > 0.001){
vec2 w = vec2(fbm(noiseUV * 0.7 + vec2(3.1, 1.7)),
              fbm(noiseUV * 0.7 + vec2(9.2, 5.3)));
noiseUV += (w - vec2(0.5)) * warp * 2.0;
}

float blobs = fbm(noiseUV);
float combinedVal = (srcLuma * sourceScale) + blobs;

// The time term is wrapped with fract() before it reaches sin(). Left
// unbounded it grows with acTime until the argument exceeds what the driver's
// precision can resolve, at which point sin() returns garbage and the whole
// effect freezes into flat bands - that was the original bug. Wrapping it also
// makes the animation loop seamlessly.
float ph = fract(acTime * phaseSpeed * 0.2);
vec3 freqRGB = vec3(1.0, 1.15, 1.3);
vec3 phaseRGB = vec3(0.0, 0.33, 0.67);
vec3 colorPhase = (combinedVal * freqColors * freqRGB) + phaseRGB + ph;
vec3 outCol = 0.5 + 0.5 * sin(colorPhase * 6.283185);

// ---- contour lines --------------------------------------------------------
// Drawn where the band value crosses an integer: these are the iridescent rings
// the effect is supposed to have, and they were missing entirely before.
if (contour > 0.001){
vec3 cf = fract(combinedVal * freqColors * freqRGB);
vec3 cd = min(cf, 1.0 - cf);
float c = 1.0 - smoothstep(0.0, 0.06 + (1.0 - contour) * 0.3, min(min(cd.x, cd.y), cd.z));
outCol = mix(outCol, vec3(1.0) - outCol, c * contour);
}

float lumaOut = gray(outCol);
outCol = mix(vec3(lumaOut), outCol, saturation);
outCol *= brightness;

float outlineMask = smoothstep(0.05, 0.3 * max(outlineStrength, 0.001), srcLuma);
outCol *= mix(1.0, outlineMask, satv(outlineStrength));

vec3 finalCol = mix(outCol, srcRGB, satv(mixWithSource));
finalCol = satv(finalCol);
// Back to premultiplied on the way out.
gl_FragColor = vec4(finalCol * sA, sA * opacity);
}
